386	/**
387	 * Produces invoice lines for only the newly purchased portion of one
388	 * certificate allocation. Existing quoted hours never appear on the overage
389	 * invoice.
390	 */
391	export function buildTrainingPlanAllocationIncreaseLineItems<
392	  T extends TrainingPlanAllocationPricedHourItem & {
393	    label?: string;
394	    productId?: string | null;
395	    productName?: string | null;
396	    lineItemTypeId?: string | null;
397	    revenueCategory?: string | null;
398	    taxCategory?: string | null;
399	  },
400	>(
401	  previousItems: T[],
402	  nextItems: T[],
403	  allocationId: string,
404	): TrainingPlanAllocationIncreaseLineItem[] {
405	  return nextItems.flatMap((nextItem, index) => {
406	    if (nextItem.groupSourceId !== allocationId) return [];
407	    const previousItem = previousItems[index];
408	    const previousHours =
409	      previousItem?.groupSourceId === allocationId
410	        ? safeNonNegative(previousItem.hours)
411	        : 0;
412	    const addedHours = money(safeNonNegative(nextItem.hours) - previousHours);
413	    if (addedHours <= 0) return [];
414	    const rate = safeNonNegative(nextItem.rate);
415	    const amount = money(addedHours * rate);
416	    if (amount <= 0) return [];
417	    return [
418	      {
419	        description:
420	          nextItem.label?.trim() ||
421	          nextItem.productName?.trim() ||
422	          'Additional training hours',
423	        quantity: addedHours,
424	        rate,
425	        amount,
426	        bucket: nextItem.bucket,
427	        productId: nextItem.productId ?? null,
428	        productName: nextItem.productName ?? null,
429	        lineItemTypeId: nextItem.lineItemTypeId ?? null,
430	        revenueCategory: nextItem.revenueCategory ?? null,
431	        taxCategory: nextItem.taxCategory ?? null,
432	      },
433	    ];
434	  });
435	}
